-- ── 010_webhook_duplicates.sql ──
-- ============================================================================
-- Webhook deliveries: remember WHEN the last repeated delivery of an event arrived.
--
-- `webhook_events` already holds one row per event (unique `dedupe_key`) and `attempts` counts every delivery of it, so a repeated delivery is
-- acknowledged, not processed again, and is visible as attempts > 1. What was missing for the audit trail ("keep a record of ignored
-- duplicates") is when the most recent repeat came in; the payment-checks screen shows it next to the delivery count.
--
-- Additive and nullable: nothing existing changes.
--
-- Rollback:
--   ALTER TABLE `webhook_events` DROP COLUMN `last_attempt_at`;
--   DELETE FROM `schema_migrations` WHERE `version` = '010_webhook_duplicates';
-- ============================================================================

SET NAMES utf8mb4;

ALTER TABLE `webhook_events`
  ADD COLUMN `last_attempt_at` DATETIME NULL AFTER `attempts`;

-- ── 011_finance_rollups.sql ──
-- ============================================================================
-- Profit Intelligence: the daily roll-up learns the costs that migration 005 made recordable.
--
-- analytics_daily is the persisted copy of App\Services\Analytics::computeDays (one SQL implementation feeds the live dashboard and the stored
-- rows, so they cannot disagree). Until now a day knew revenue, provider (SMM) cost and advertising only. It now also keeps, per business day
-- (the day the payment was verified, Asia/Kolkata):
--
--   fulfil_cost_paise / payment_fee_paise / other_cost_paise   the order cost lines (order_costs) of the orders paid that day
--   chargebacks_paise                                          chargebacks recorded that day (expenses.category = chargeback)
--   expenses_paise                                             other business expenses recorded that day (tools, hosting, other)
--   ads_actual_paise / ads_estimated_paise / ads_actual_day    advertising: what was actually spent, what the CPC model estimates, and which
--                                                              of the two ads_spend_paise carries (actual replaces the estimate for a day that has
--                                                              actual spend — the two are never added together)
--   orders_cost_estimated / orders_cost_incomplete             how many orders paid that day have an estimated / an unknown cost
--
-- Nothing is lost: existing columns keep their names; for a day with no cost lines, no expenses and no actual ad spend every figure is exactly what it
-- was before. Every stored day is marked dirty so it is recomputed with the new columns the next time it is read.
--
-- Rollback (only needed to go back to the previous release; the columns are derived data):
--   ALTER TABLE `analytics_daily` DROP COLUMN `orders_cost_incomplete`, DROP COLUMN `orders_cost_estimated`, DROP COLUMN `ads_actual_day`,
--     DROP COLUMN `ads_estimated_paise`, DROP COLUMN `ads_actual_paise`, DROP COLUMN `expenses_paise`, DROP COLUMN `chargebacks_paise`,
--     DROP COLUMN `other_cost_paise`, DROP COLUMN `payment_fee_paise`, DROP COLUMN `fulfil_cost_paise`;
--   DELETE FROM `schema_migrations` WHERE `version` = '011_finance_rollups';
-- ============================================================================

SET NAMES utf8mb4;

ALTER TABLE `analytics_daily`
  ADD COLUMN `fulfil_cost_paise`      BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `smm_spend_paise`,
  ADD COLUMN `payment_fee_paise`      BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `fulfil_cost_paise`,
  ADD COLUMN `other_cost_paise`       BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `payment_fee_paise`,
  ADD COLUMN `chargebacks_paise`      BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `other_cost_paise`,
  ADD COLUMN `expenses_paise`         BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `chargebacks_paise`,
  ADD COLUMN `ads_actual_paise`       BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `ads_spend_paise`,
  ADD COLUMN `ads_estimated_paise`    BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER `ads_actual_paise`,
  ADD COLUMN `ads_actual_day`         TINYINT(1) NOT NULL DEFAULT 0 AFTER `ads_estimated_paise`,
  ADD COLUMN `orders_cost_estimated`  INT UNSIGNED NOT NULL DEFAULT 0 AFTER `orders_completed`,
  ADD COLUMN `orders_cost_incomplete` INT UNSIGNED NOT NULL DEFAULT 0 AFTER `orders_cost_estimated`;

UPDATE `analytics_daily` SET `dirty` = 1;

-- ── 012_visitor_day_campaign.sql ──
-- ============================================================================
-- Ads Intelligence: which campaign a visitor-day belongs to.
--
-- visitor_days is the unit the CPC estimate is billed on (one row per visitor per business day) and the unit the dashboard counts visitors in. To
-- split visitors, qualified visitors, checkout starts and the estimated spend BY CAMPAIGN so that the campaign rows add up exactly to the dashboard's
-- totals, every visitor-day needs one campaign key:
--
--   visitor_days.utm_campaign   the campaign tag of the FIRST campaign-tagged session the visitor had that business day (NULL = none: the visitor
--                               came directly, from a site, or without a tag). Written by the visitor tracker; never changed afterwards.
--
-- Existing rows are filled in best effort from the session rows that still exist (the first tagged session of the same visitor on the same day).
-- Rows whose sessions were already purged stay NULL = "no campaign": older history is not invented.
--
-- Rollback: ALTER TABLE `visitor_days` DROP KEY `idx_vdays_campaign`, DROP COLUMN `utm_campaign`;
--   DELETE FROM `schema_migrations` WHERE `version` = '012_visitor_day_campaign';
-- ============================================================================

SET NAMES utf8mb4;

ALTER TABLE `visitor_days`
  ADD COLUMN `utm_campaign` VARCHAR(80) NULL AFTER `device_type`,
  ADD KEY `idx_vdays_campaign` (`day`, `utm_campaign`);

UPDATE `visitor_days` vd
   SET vd.`utm_campaign` = (
         SELECT s.`utm_campaign` FROM `visitor_sessions` s
          WHERE s.`visitor_id` = vd.`visitor_id` AND s.`day` = vd.`day` AND s.`utm_campaign` IS NOT NULL
          ORDER BY s.`started_at`, s.`id` LIMIT 1)
 WHERE vd.`utm_campaign` IS NULL;

-- ── 013_order_calculator.sql ──
-- ============================================================================
-- Centralized order calculation: an explicit, per-service pricing-unit model so a
-- customer's requested quantity and the provider's billing unit are never confused
-- with each other or with the rupee price — see App\Services\OrderCalculator.
--
-- Pricing models (services.pricing_model):
--   fixed_package  one pack of `quantity` units for `price_paise`. The customer cannot
--                   change how many are bought — today's existing, unchanged behaviour.
--   per_unit        `price_paise` buys `pricing_unit_qty` units; the customer may request
--                   any positive whole multiple of `pricing_unit_qty` (this also covers
--                   "buy N packs of a fixed size" — the maths is identical).
--
-- Provider quantity: `services.provider_qty_divisor` converts the customer-facing unit
-- count into whatever unit the SMM provider bills in (normally 1 — same units). If the
-- requested quantity does not divide evenly by it, OrderCalculator REJECTS the order
-- rather than rounding, and the service is flagged for admin review.
--
-- `services.config_version` is bumped whenever a pricing-relevant field changes
-- (price, quantity, min/max, pricing model, unit size, provider divisor); every order
-- snapshots the version it was calculated against, so a later edit to a service can
-- never silently re-price or re-interpret an order that has already been placed.
--
-- Rollback:
--   ALTER TABLE `orders` DROP COLUMN `provider_quantity`, DROP COLUMN `pricing_model`, DROP COLUMN `config_version`;
--   ALTER TABLE `services` DROP COLUMN `pricing_model`, DROP COLUMN `pricing_unit_qty`, DROP COLUMN `provider_qty_divisor`, DROP COLUMN `config_version`;
--   DELETE FROM schema_migrations WHERE version = '013_order_calculator';
-- ============================================================================

SET NAMES utf8mb4;

ALTER TABLE `services`
  ADD COLUMN `pricing_model`        VARCHAR(16)  NOT NULL DEFAULT 'fixed_package' AFTER `quantity`,
  ADD COLUMN `pricing_unit_qty`     INT UNSIGNED NULL AFTER `pricing_model`,
  ADD COLUMN `provider_qty_divisor` INT UNSIGNED NOT NULL DEFAULT 1 AFTER `smm_cost_paise`,
  ADD COLUMN `config_version`       INT UNSIGNED NOT NULL DEFAULT 1 AFTER `updated_at`;

ALTER TABLE `orders`
  ADD COLUMN `provider_quantity` INT UNSIGNED NULL AFTER `quantity`,                       -- exact quantity submitted to the provider; NULL until computed
  ADD COLUMN `pricing_model`     VARCHAR(16)  NOT NULL DEFAULT 'fixed_package' AFTER `provider_quantity`,
  ADD COLUMN `config_version`    INT UNSIGNED NOT NULL DEFAULT 1 AFTER `pricing_model`;    -- services.config_version this order was validated against

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE IF NOT EXISTS `schema_migrations` (`version` VARCHAR(64) NOT NULL, `applied_at` DATETIME NOT NULL, PRIMARY KEY (`version`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
